actions.script:
const msgMap = {
    typeString: notificationType,
    device: { deviceId: device.deviceId, deviceName: device.deviceName },
    message: message
};

const nm = ec.makeNotificationMessage().topic(notificationTopic).title(notificationTitle || "");
nm.message(msgMap);
nm.type(notificationType);
nm.showAlert(true).persistOnSend(true).send();

const deviceConfig = ec.entity.find("moqui.device.DeviceConfig")
    .condition("deviceConfigId", deviceConfigId)
    .useCache(true)
    .one();
if (!deviceConfig) {
    ec.message.addError(`DeviceConfig not found for deviceConfigId [${deviceConfigId}].`);
    return;
}

const device = ec.entity.find("moqui.device.Device")
    .condition("deviceId", deviceId)
    .useCache(false)
    .one();
if (!device) {
    ec.message.addError(`Device not found for deviceId [${deviceId}].`);
    return;
}

if (validateDeviceType && deviceConfig.deviceTypeEnumId) {
    const enumResult = ec.service.sync().name("org.moqui.impl.BasicServices.find#EnumerationByParent")
        .parameters({
            parentEnumId: deviceConfig.deviceTypeEnumId,
            includeParent: true,
            includeNested: true,
            orderByField: "description"
        }).call();

    const enumIdSet = enumResult.enumIdSet;
    const hasType = Array.isArray(enumIdSet) ? enumIdSet.includes(device.deviceTypeEnumId)
        : (enumIdSet && typeof enumIdSet.has === 'function' ? enumIdSet.has(device.deviceTypeEnumId)
        : (enumIdSet && typeof enumIdSet.includes === 'function' ? enumIdSet.includes(device.deviceTypeEnumId) : false));

    if (!hasType) {
        ec.message.addError(`Device [${deviceId}] with type [${device.deviceTypeEnumId}] is not compatible with DeviceConfig [${deviceConfigId}] type [${deviceConfig.deviceTypeEnumId}].`);
        return;
    }
}

sourceParameterCount = 0;
targetParameterCount = 0;
commonParameterCount = 0;
updatedParameterCount = 0;
skippedParameterKeySet = [];
updatedParameterIdList = [];
updatedDeviceFieldList = [];

if (copyDeviceFields) {
    let deviceChanged = false;

    if (deviceConfig.controlMethodEnumId && device.controlMethodEnumId !== deviceConfig.controlMethodEnumId) {
        updatedDeviceFieldList.push("controlMethodEnumId");
        if (!dryRun) {
            device.controlMethodEnumId = deviceConfig.controlMethodEnumId;
            deviceChanged = true;
        }
    }

    if (deviceConfig.approximatedFunctionId && device.approximatedFunctionId !== deviceConfig.approximatedFunctionId) {
        updatedDeviceFieldList.push("approximatedFunctionId");
        if (!dryRun) {
            device.approximatedFunctionId = deviceConfig.approximatedFunctionId;
            deviceChanged = true;
        }
    }

    if (deviceChanged && !dryRun) device.update();
}

const sourceParameterList = ec.entity.find("moqui.math.Parameter")
    .condition("deviceConfigId", deviceConfigId)
    .useCache(true)
    .list();

const targetParameterList = ec.entity.find("moqui.math.Parameter")
    .condition("deviceId", deviceId)
    .useCache(false)
    .list();

sourceParameterCount = sourceParameterList ? sourceParameterList.length : 0;
targetParameterCount = targetParameterList ? targetParameterList.length : 0;

const makeParameterKey = (param) => {
    const parameterDefId = param.parameterDefId ? String(param.parameterDefId) : "";
    const parameterAlias = param.parameterAlias ? String(param.parameterAlias) : "";
    return `${parameterDefId}|${parameterAlias}`;
};

const sourceByKey = {};
const duplicateSourceKeys = [];
for (const sourceParam of (sourceParameterList || [])) {
    if (!sourceParam.parameterDefId) continue;
    const key = makeParameterKey(sourceParam);
    if (sourceByKey[key]) duplicateSourceKeys.push(key);
    else sourceByKey[key] = sourceParam;
}
if (duplicateSourceKeys.length > 0) {
    ec.message.addError(`DeviceConfig [${deviceConfigId}] has duplicate Parameters for parameterDefId|parameterAlias key(s): ${duplicateSourceKeys.join(', ')}. Cannot apply DeviceConfig safely.`);
    return;
}

const targetByKey = {};
const duplicateTargetKeys = [];
for (const targetParam of (targetParameterList || [])) {
    if (!targetParam.parameterDefId) continue;
    const key = makeParameterKey(targetParam);
    if (targetByKey[key]) duplicateTargetKeys.push(key);
    else targetByKey[key] = targetParam;
}
if (duplicateTargetKeys.length > 0) {
    ec.message.addError(`Device [${deviceId}] has duplicate Parameters for parameterDefId|parameterAlias key(s): ${duplicateTargetKeys.join(', ')}. Cannot apply DeviceConfig safely.`);
    return;
}

for (const [key, sourceParam] of Object.entries(sourceByKey)) {
    const targetParam = targetByKey[key];

    if (!targetParam) {
        skippedParameterKeySet.push(key);
        continue;
    }

    commonParameterCount++;
    let parameterChanged = false;

    if (targetParam.numericValue !== sourceParam.numericValue) {
        parameterChanged = true;
        if (!dryRun) targetParam.numericValue = sourceParam.numericValue;
    }
    if (targetParam.symbolicValue !== sourceParam.symbolicValue) {
        parameterChanged = true;
        if (!dryRun) targetParam.symbolicValue = sourceParam.symbolicValue;
    }
    if (targetParam.parameterEnumId !== sourceParam.parameterEnumId) {
        parameterChanged = true;
        if (!dryRun) targetParam.parameterEnumId = sourceParam.parameterEnumId;
    }
    if (copySequenceNum && targetParam.sequenceNum !== sourceParam.sequenceNum) {
        parameterChanged = true;
        if (!dryRun) targetParam.sequenceNum = sourceParam.sequenceNum;
    }

    if (parameterChanged) {
        updatedParameterCount++;
        updatedParameterIdList.push(targetParam.parameterId);
        if (!dryRun) targetParam.update();
    }
}

service-call.in-map:
{device:device, request:request,
                connection:connection, deviceContentId:deviceContentId, transferFiles:transferFiles, payload:payload,
                bulkRequestItemList:bulkRequestItemList, requestItemList:requestItemList}

if.script:
secondaryResults = [];
for (const mirror of (mirrorRequestList || [])) {
    let out = null, failure = null;
    try {
        out = ec.service.sync().name("moqui.device.DeviceServices.run#DeviceRequest").parameters({
            requestName: mirror.requestName, deviceContentId: deviceContentId, transferFiles: transferFiles}).call();
    } catch (e) {
        failure = String(e.message || e);
    }
    // a failed destination keeps its own error; this request completed
    if (ec.message.hasError()) {
        failure = failure || ec.message.getErrorsString();
        ec.message.clearErrors();
    }
    secondaryResults.push({requestName: mirror.requestName, status: failure ? (out?.status || 'failed') : out?.status,
        transferredFiles: out?.transferredFiles || [], errorMessage: failure || out?.errorMessage || null});
}
